$('#s3-breadcrumbs').onclick=e=>{const crumb=e.target.closest('[data-s3-prefix]');if(crumb)loadS3(crumb.dataset.s3Prefix).catch(err=>toast(err.message))};
$('#s3-browser').onclick=e=>{const folder=e.target.closest('[data-s3-folder]');if(folder)loadS3([s3Prefix,folder.dataset.s3Folder].filter(Boolean).join('/')).catch(err=>toast(err.message))};
function useS3Destination(prefix){if(!prefix)return toast('Choose or enter a destination folder');$('#archive-destination-mode').value='custom';$('#archive-destination').value=prefix;$('#archive-custom-destination').hidden=false;renderArchiveSelection();showView('archive');toast('TAR archive destination selected')}
$('#use-s3-location').onclick=()=>useS3Destination(s3Prefix);
$('#use-new-s3-location').onclick=()=>{const value=$('#s3-new-folder').value.trim().replace(/^\/+|\/+$/g,'');if(!value||value.split('/').some(part=>!part||part==='.'||part==='..'))return toast('Enter a valid subfolder name');useS3Destination([s3Prefix,value].filter(Boolean).join('/'))};
$('#refresh-upload-browser').onclick=()=>loadUploadBrowser();
$('#upload-now-breadcrumbs').onclick=e=>{const crumb=e.target.closest('[data-upload-path]');if(crumb)loadUploadBrowser(crumb.dataset.uploadPath)};
$('#upload-now-browser').onclick=e=>{const select=e.target.closest('.select-upload-item,.choose-upload-item');if(select)return selectUploadNow(select.dataset.path);const folder=e.target.closest('.open-upload-folder');if(folder)loadUploadBrowser(folder.dataset.path)};
$('#queue-upload-now').onclick=async()=>{if(!uploadNowSelected)return toast('Select a file or folder');if(!stateData?.runner?.capabilities?.includes('upload-now-v1'))return toast('The runner is updating. Wait a few seconds and try again.');if(!window.confirm(`Upload ${uploadNowSelected} now?`))return;const button=$('#queue-upload-now');button.disabled=true;try{await api('/api/upload-now',{method:'POST',body:JSON.stringify({path:uploadNowSelected})});uploadNowSelected='';$('#upload-now-selection').hidden=true;toast('Upload now queued');await load();showView('activity')}catch(err){toast(err.message)}finally{button.disabled=false}};
async function cancelCurrentJob(){const job=stateData.active[0];if(!job)return;try{await api(`/api/runs/${job.id}/cancel`,{method:'POST',body:'{}'});toast('Cancellation requested');$('#cancel-help').showModal();await load()}catch(e){toast(e.message)}}
$('#cancel-job').onclick=cancelCurrentJob;$('#activity-cancel').onclick=cancelCurrentJob;
$('#close-cancel-help').onclick=()=>$('#cancel-help').close();$('#copy-hard-kill').onclick=async()=>{const command=$('#hard-kill-command').textContent;try{await navigator.clipboard.writeText(command);toast('Hard-kill command copied')}catch{$('#hard-kill-command').focus();const selection=window.getSelection(),range=document.createRange();range.selectNodeContents($('#hard-kill-command'));selection.removeAllRanges();selection.addRange(range);toast('Command selected. Copy it manually.')}};
function refreshVisibleSelection(){$$('.tree-node').forEach(n=>{const box=n.querySelector(':scope > .tree-row .tree-check');if(!box)return;const state=selectionState(n.dataset.path);box.checked=state==='checked';box.dataset.partial=String(state==='partial')});setPartialCheckboxes()}
document.addEventListener('change',e=>{if(e.target.matches('.archive-tree-check')){const path=e.target.closest('.archive-tree-node').dataset.path;if(e.target.checked){for(const source of [...archiveSelected.keys()])if(source===path||source.startsWith(path+'/'))archiveSelected.delete(source);const ancestor=[...archiveSelected.entries()].map(([source,value])=>({source,...value})).filter(item=>path.startsWith(item.source+'/')).sort((a,b)=>b.source.length-a.source.length)[0];if(ancestor&&archivePathExcluded(ancestor,path)){archiveSelected.set(path,{exclusions:new Set()})}else if(!ancestor){archiveSelected.set(path,{exclusions:new Set()})}else{for(const value of [...ancestor.exclusions])if(value===relativeTo(ancestor.source,path)||value.startsWith(relativeTo(ancestor.source,path)+'/'))ancestor.exclusions.delete(value)}}else{const cover=archiveCovering(path);for(const source of [...archiveSelected.keys()])if(source===path||source.startsWith(path+'/'))archiveSelected.delete(source);if(cover&&cover.source!==path)archiveSelected.get(cover.source).exclusions.add(relativeTo(cover.source,path))}renderArchiveSelection();refreshArchiveSelection();return}if(e.target.matches('.tree-check')){const node=e.target.closest('.tree-node'),path=node.dataset.path,current=selectionState(path);if(e.target.checked){for(const source of [...draftMappings.keys()])if(source===path||source.startsWith(path+'/'))draftMappings.delete(source);const ancestor=[...draftMappings.entries()].map(([source,value])=>({source,...value})).filter(m=>path.startsWith(m.source+'/')).sort((a,b)=>b.source.length-a.source.length)[0];if(ancestor&&pathIsExcluded(ancestor,path)){draftMappings.set(path,{destination:`${ancestor.destination}/${relativeTo(ancestor.source,path)}`,exclusions:new Set()})}else if(!ancestor){draftMappings.set(path,{destination:defaultPrefix(path),exclusions:new Set()})}else{for(const exclusion of [...ancestor.exclusions])if(exclusion===relativeTo(ancestor.source,path)||exclusion.startsWith(relativeTo(ancestor.source,path)+'/'))ancestor.exclusions.delete(exclusion)}}else{const cover=coveringMapping(path);for(const source of [...draftMappings.keys()])if(source===path||source.startsWith(path+'/'))draftMappings.delete(source);if(cover&&cover.source!==path){const original=draftMappings.get(cover.source);original.exclusions.add(relativeTo(cover.source,path))}}renderDraftMappings();refreshVisibleSelection()}if(e.target.matches('.draft-prefix')){const mapping=draftMappings.get(e.target.dataset.source);if(mapping)mapping.destination=e.target.value}});
$('#archive-destination-mode').onchange=()=>{const mode=$('#archive-destination-mode').value,custom=mode==='custom';$('#archive-custom-destination').hidden=!custom;$('#archive-destination-help').innerHTML=mode==='source'?'Inside a matching folder sends <strong>/volume3/Docker/Persistent</strong> to <strong>Docker/Persistent/Persistent_YYYY-MM-DD.tar</strong>.':mode==='parent'?'Directly in the parent sends <strong>/volume3/Work/_WEBSITES/folder_1</strong> to <strong>Work/_WEBSITES/folder_1_YYYY-MM-DD.tar</strong>.':'Every selected folder is uploaded beneath the custom S3 prefix.';renderArchiveSelection()};
$('#archive-destination').oninput=renderArchiveSelection;
$('#create-archive').onclick=async()=>{if(!archiveSelected.size)return toast('Select at least one folder');if(!stateData?.runner?.capabilities?.includes('folder-archive-v4'))return toast('The runner is updating. Wait a few seconds and try again.');const destinationMode=$('#archive-destination-mode').value;if(destinationMode==='custom'&&!$('#archive-destination').value.trim())return toast('Choose an S3 destination');if(!window.confirm(`Create and upload ${archiveSelected.size} dated archive${archiveSelected.size===1?'':'s'}?`))return;const button=$('#create-archive');button.disabled=true;try{const sources=[...archiveSelected].map(([source,value])=>({source,exclusions:[...value.exclusions]}));await api('/api/archive',{method:'POST',body:JSON.stringify({sources,destination:$('#archive-destination').value,destination_mode:destinationMode,format:$('#archive-format').value})});toast('Archive job queued');archiveSelected.clear();renderArchiveSelection();refreshArchiveSelection();await load();showView('activity')}catch(e){toast(e.message)}finally{button.disabled=false}};
$('#save-selection').onclick=async()=>{try{const mappings=[...draftMappings].map(([source,mapping])=>({source,destination:mapping.destination,exclusions:[...mapping.exclusions],enabled:true}));await api('/api/mappings/replace',{method:'POST',body:JSON.stringify({mappings})});await load();toast('Folder coverage saved')}catch(e){toast(e.message)}};
$('#measure-storage').onclick=()=>queueStorage('/api/s3/size','Size measurement');$('#refresh-billing').onclick=()=>queueStorage('/api/billing/refresh','Bill refresh');$('#cost-rate').onchange=saveCost;$('#cost-est').onclick=()=>setCostMode('estimate');$('#cost-act').onclick=()=>setCostMode('actual');$('#cost-auto').onchange=saveCost;
$('#save-schedule').onclick=async()=>{try{await api('/api/settings',{method:'POST',body:JSON.stringify({schedule:{time:$('#schedule-time').value,max_age_hours:Number($('#max-age').value),full_scan_days:Number($('#full-scan').value),enabled:$('#schedule-enabled').checked},safety:{paused:!$('#runner-enabled').checked},custom_exclusions:stateData.config.custom_exclusions})});scheduleDirty=false;$('#schedule-save-state').textContent='';await load();toast('Safety and schedule saved')}catch(e){toast(e.message)}};
$('#exclusions').oninput=()=>{exclusionsDirty=true};
$('#save-settings').onclick=async()=>{try{await api('/api/settings',{method:'POST',body:JSON.stringify({schedule:stateData.config.schedule,custom_exclusions:$('#exclusions').value.split('\n')})});exclusionsDirty=false;await load();toast('Backup exclusions saved')}catch(e){toast(e.message)}};
function updateTemperatureLabels(){$('#temp-pause-value').textContent=$('#temp-pause').value;$('#temp-resume-value').textContent=$('#temp-resume').value}
function markPerformanceDirty(){performanceDirty=true;updateTemperatureLabels();const state=$('#performance-save-state');state.textContent='Unsaved changes';state.classList.add('dirty')}
$('#schedule').addEventListener('input',e=>{if(e.target.matches('#schedule-time,#max-age,#full-scan,#schedule-enabled,#runner-enabled'))markScheduleDirty()});$('#schedule').addEventListener('change',e=>{if(e.target.matches('#schedule-enabled,#runner-enabled'))markScheduleDirty()});
$('#settings').addEventListener('input',e=>{if(e.target.matches('#scan-batch,#scan-pause,#transfers,#checkers,#cpu-cores,#bandwidth,#request-rate,#temp-pause,#temp-resume'))markPerformanceDirty()});
$('#save-performance').onclick=async()=>{try{const performance={scan_batch_entries:Number($('#scan-batch').value),scan_pause_ms:Number($('#scan-pause').value),transfers:Number($('#transfers').value),checkers:Number($('#checkers').value),rclone_cpu_cores:Number($('#cpu-cores').value),bandwidth_mib:Number($('#bandwidth').value),s3_requests_per_second:Number($('#request-rate').value),temperature_pause_c:Number($('#temp-pause').value),temperature_resume_c:Number($('#temp-resume').value)};if(performance.temperature_resume_c>=performance.temperature_pause_c)throw Error('Resume temperature must be lower than pause temperature');await api('/api/settings',{method:'POST',body:JSON.stringify({schedule:stateData.config.schedule,performance,custom_exclusions:stateData.config.custom_exclusions})});performanceDirty=false;const state=$('#performance-save-state');state.textContent='Settings are up to date';state.classList.remove('dirty');await load();toast('Performance limits saved')}catch(e){toast(e.message)}};
$('#restart-runner').onclick=async()=>{const button=$('#restart-runner');button.disabled=true;try{await api('/api/runner/restart',{method:'POST',body:'{}'});toast('Runner restart requested');setTimeout(()=>load().catch(()=>{}),5000)}catch(e){toast(e.message)}finally{setTimeout(()=>{button.disabled=false},5000)}};
$('#rclone-auth').onchange=()=>{$('#rclone-key-fields').hidden=$('#rclone-auth').value==='environment'};
$('#refresh-rclone').onclick=refreshRcloneStatus;
$('#configure-rclone').onclick=async()=>{const button=$('#configure-rclone'),authMode=$('#rclone-auth').value,payload={auth_mode:authMode,confirmation:$('#rclone-confirm').value};if(authMode==='keys'){payload.access_key_id=$('#rclone-access-key').value.trim();payload.secret_access_key=$('#rclone-secret-key').value}button.disabled=true;try{const request=await api('/api/rclone/configure',{method:'POST',body:JSON.stringify(payload)});$('#rclone-config-status').textContent='The runner is securely updating aws-archive…';const result=await waitForRclone(request.id);if(result.status==='failed')throw Error(result.error||'Configuration failed');toast('aws-archive configuration saved')}catch(e){toast(e.message);await loadRcloneStatus().catch(()=>{})}finally{$('#rclone-access-key').value='';$('#rclone-secret-key').value='';$('#rclone-confirm').value='';button.disabled=false}};
let runLog={text:'',id:'',started:'',mode:''};
$('#run-detail .diagnostic-log').addEventListener('toggle',e=>{const pre=$('#detail-log');if(e.target.open&&!pre.textContent)pre.textContent=runLog.text});
$('#copy-log').onclick=async()=>{const st=$('#log-state');try{await navigator.clipboard.writeText(runLog.text);st.textContent='Copied'}catch{const ta=document.createElement('textarea');ta.value=runLog.text;ta.style.position='fixed';ta.style.opacity='0';document.body.append(ta);ta.select();try{document.execCommand('copy');st.textContent='Copied'}catch{st.textContent='Copy failed — use Download'}ta.remove()}setTimeout(()=>{st.textContent=''},2500)};
$('#download-log').onclick=()=>{const stamp=(runLog.started||'').slice(0,16).replace(/[:T]/g,'-')||'run',blob=new Blob([runLog.text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`glacier-${runLog.mode||'run'}-${stamp}.txt`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('#close-detail').onclick=()=>$('#run-detail').close();$('#run-detail').addEventListener('close',()=>{liveOpen=false;$('#live-cancel').hidden=true;$('#run-detail .diagnostic-log').hidden=false});$('#live-cancel').onclick=async()=>{await cancelCurrentJob();renderLive()};$('#ab-details').onclick=openLive;
$('#run-detail').addEventListener('click',event=>{const dialog=$('#run-detail'),rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close()});
function showAuth(configured){authConfigured=configured;$('#auth-gate').hidden=false;$('#auth-title').textContent=configured?'Sign in':'Secure your archive manager';$('#auth-intro').textContent='Create the administrator account for this installation.';$('#auth-intro').hidden=configured;$('#auth-submit').textContent=configured?'Sign in':'Create administrator';$('#auth-password').autocomplete=configured?'current-password':'new-password';$('#password-rules').hidden=configured;$('#forgot-password').hidden=!configured;$('#auth-error').textContent='';}
function passwordRuleState(){const value=$('#auth-password').value,rules={length:value.length>=12,lower:/[a-z]/.test(value),upper:/[A-Z]/.test(value),number:/[0-9]/.test(value),symbol:/[^A-Za-z0-9]/.test(value)};Object.entries(rules).forEach(([rule,valid])=>$(`[data-rule="${rule}"]`).classList.toggle('valid',valid))}
$('#auth-password').addEventListener('input',passwordRuleState);
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();$('#auth-error').textContent='';try{const route=authConfigured?'/api/auth/login':'/api/auth/setup';const result=await api(route,{method:'POST',body:JSON.stringify({username:$('#auth-username').value,password:$('#auth-password').value})});csrfToken=result.csrf;$('#auth-password').value='';$('#auth-gate').hidden=true;$('#signed-in-user').textContent=result.username;await load();applyRoute()}catch(err){$('#auth-error').textContent=err.message}});
$('#logout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'})}finally{csrfToken='';stateData=null;showAuth(true)}};
$('#forgot-password').onclick=()=>$('#password-reset').showModal();
$('#close-password-reset').onclick=()=>$('#password-reset').close();
$('#copy-password-reset').onclick=async()=>{try{await navigator.clipboard.writeText($('#password-reset-command').textContent);toast('Reset command copied')}catch{toast('Select and copy the command manually')}};
$('#password-reset').addEventListener('click',event=>{const dialog=$('#password-reset'),rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close()});
async function boot(){try{const status=await api('/api/auth/status');if(!status.configured||!status.authenticated){showAuth(status.configured);return}csrfToken=status.csrf;$('#signed-in-user').textContent=status.username;await load();applyRoute()}catch(err){showAuth(true);$('#auth-error').textContent=err.message}}
boot();setInterval(()=>{if(csrfToken)load().catch(()=>{})},3000);
